for _ in range(int(input())):
	n = int(input())
	l = [[0 for i in range(n)] for j in range(n)]
	c = (n + 1) // 2
	for i in range(n // 2 + 1):
		l[c - 1 + i][i] = 1
	for i in range(n // 2):
		l[i][c + i] = 1
	for i in range(n):
		e = l[i].index(1)
		for j in range(1, n):
			l[i][e - j] = j + 1
	for i in range(n):
		print(*l[i])
